13	#ifndef TREM_HPP
14	#define TREM_HPP
15	
16	#include <pto/common/constants.hpp>
17	
18	namespace pto {
19	// Formula: remainder(a, b) = a - floor(a/b) * b
20	// Note: For fp32, after computing remainder, we check if result * divider < 0.
21	//       If signs differ, we add divider to result to ensure the result has the same sign as divider.
22	template <typename T, unsigned dstRowStride>
23	struct RemOp {
24	    PTO_INTERNAL static void RemF32Instr(
25	        __ubuf__ float* dst, __ubuf__ float* src0, __ubuf__ float* src1, __ubuf__ float* tmp, unsigned repeatTimes,
26	        unsigned validCols)
27	    {
28	        set_mask_count();
29	        set_vector_mask(0, validCols);
30	        vdiv(tmp, src0, src1, 1, 1, 1, 1, 8, 8, 8);
31	        pipe_barrier(PIPE_V);
32	
33	        vconv_f322f32f(tmp, tmp, 1, 1, 1, 8, 8);
34	        pipe_barrier(PIPE_V);
35	
36	        vmul(dst, tmp, src1, 1, 1, 1, 1, 8, 8, 8);
37	        pipe_barrier(PIPE_V);
38	
39	        vsub(dst, src0, dst, 1, 1, 1, 1, 8, 8, 8);
40	        pipe_barrier(PIPE_V);
41	        vmul(tmp, dst, src1, 1, 1, 1, 1, 8, 8, 8);
42	        pipe_barrier(PIPE_V);
43	
44	        // vcmpvs_lt must run in norm mask mode with explicit repeatTimes: unlike
45	        // arithmetic ops, the compare op does not auto-extend a single repeat to
46	        // the whole count (CANN CompareScalarCompute passes ceil(count*sizeof(T)/256)
47	        // repeats), so repeat=1 would only emit the first 64 bits of the packed
48	        // mask and leave stale UB in the rest.
49	        __ubuf__ uint8_t* cmpMask = reinterpret_cast<__ubuf__ uint8_t*>(tmp + dstRowStride);
50	        set_mask_norm();
51	        set_vector_mask(-1, -1);
52	        vcmpvs_lt(cmpMask, tmp, 0.0f, repeatTimes, 1, 1, 8, 8);
53	        pipe_barrier(PIPE_V);
54	        set_mask_count();
55	        set_vector_mask(0, validCols);
56	
57	        vadd(tmp, dst, src1, 1, 1, 1, 1, 8, 8, 8);
58	        pipe_barrier(PIPE_V);
59	
60	        // VSEL_TENSOR_TENSOR_MODE (2) reads the packed bitmask from UB through a
61	        // two-level address indirection: set_cmpmask must receive a buffer holding
62	        // the mask's address, replicated over cmpmaskLen uint32 lanes (64-bit for
63	        // B32, same convention as TSel). cmpMask occupies
64	        // dstRowStride..dstRowStride+maskFloats, addrBuf follows it, aligned to 32 bytes.
65	        unsigned maskBytes = CeilDivision(dstRowStride, BIT_TO_BYTE);
66	        unsigned maskFloats = CeilDivision(maskBytes, BLOCK_BYTE_SIZE) * BIT_TO_BYTE;
67	        constexpr unsigned cmpmaskLen = 2; // 64-bit address for B32 dtype
68	        __ubuf__ uint32_t* addrBuf = reinterpret_cast<__ubuf__ uint32_t*>(tmp + dstRowStride + maskFloats);
69	        uint32_t maskAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpMask));
70	        set_vector_mask(0, cmpmaskLen);
71	        vector_dup(addrBuf, maskAddr, 1, 1, 1, 8, 0);
72	        pipe_barrier(PIPE_V);
73	        set_cmpmask(addrBuf);
74	        pipe_barrier(PIPE_V);
75	        set_vector_mask(0, validCols);
76	        vsel(dst, tmp, dst, 1, 1, 1, 1, 8, 8, 8, 2);
77	        pipe_barrier(PIPE_V);
78	    }
79	
80	    PTO_INTERNAL static void RemInt32Instr(
81	        __ubuf__ int32_t* dst, __ubuf__ int32_t* src0, __ubuf__ int32_t* src1, __ubuf__ int32_t* tmp,
82	        unsigned repeatTimes, unsigned validCols)
83	    {
84	        __ubuf__ float* dst_f = reinterpret_cast<__ubuf__ float*>(dst);
85	        __ubuf__ float* src0_f = reinterpret_cast<__ubuf__ float*>(src0);
86	        __ubuf__ float* src1_f = reinterpret_cast<__ubuf__ float*>(src1);
87	        __ubuf__ float* tmp_f = reinterpret_cast<__ubuf__ float*>(tmp);
88	
89	        set_mask_count();
90	        set_vector_mask(0, validCols);
91	
92	        vconv_s322f32(src0_f, src0, 1, 1, 1, 8, 8);
93	        vconv_s322f32(src1_f, src1, 1, 1, 1, 8, 8);
94	        pipe_barrier(PIPE_V);
95	
96	        vdiv(tmp_f, src0_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
97	        pipe_barrier(PIPE_V);
98	
99	        vconv_f322s32f(tmp, tmp_f, 1, 1, 1, 8, 8);
100	        pipe_barrier(PIPE_V);
101	
102	        vconv_f322s32r(src0, src0_f, 1, 1, 1, 8, 8);
103	        vconv_f322s32r(src1, src1_f, 1, 1, 1, 8, 8);
