105	        vmul(dst, tmp, src1, 1, 1, 1, 1, 8, 8, 8);
106	        pipe_barrier(PIPE_V);
107	
108	        vsub(dst, src0, dst, 1, 1, 1, 1, 8, 8, 8);
109	        pipe_barrier(PIPE_V);
110	
111	        vconv_s322f32(dst_f, dst, 1, 1, 1, 8, 8);
112	        vconv_s322f32(src1_f, src1, 1, 1, 1, 8, 8);
113	        pipe_barrier(PIPE_V);
114	        vmul(tmp_f, dst_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
115	        pipe_barrier(PIPE_V);
116	
117	        // Same norm-mode compare with explicit repeatTimes as the f32 path.
118	        __ubuf__ uint8_t* cmpMask = reinterpret_cast<__ubuf__ uint8_t*>(tmp + dstRowStride);
119	        set_mask_norm();
120	        set_vector_mask(-1, -1);
121	        vcmpvs_lt(cmpMask, tmp_f, 0.0f, repeatTimes, 1, 1, 8, 8);
122	        pipe_barrier(PIPE_V);
123	        set_mask_count();
124	        set_vector_mask(0, validCols);
125	
126	        vadd(tmp_f, dst_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
127	        pipe_barrier(PIPE_V);
128	
129	        // VSEL_TENSOR_TENSOR_MODE (2): same 64-bit address buffer as the f32 path.
130	        unsigned maskByte = CeilDivision(dstRowStride, BIT_TO_BYTE); // shape
131	        unsigned maskFloat = CeilDivision(maskByte, BLOCK_BYTE_SIZE) * BIT_TO_BYTE;
132	        constexpr unsigned cmpmaskLen = 2; // 64-bit address for B32 dtype
133	        __ubuf__ uint32_t* addrBufs = reinterpret_cast<__ubuf__ uint32_t*>(tmp + dstRowStride + maskFloat);
134	        uint32_t maskAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpMask));
135	        set_vector_mask(0, cmpmaskLen);
136	        vector_dup(addrBufs, maskAddr, 1, 1, 1, 8, 0);
137	        pipe_barrier(PIPE_V);
138	        set_cmpmask(addrBufs);
139	        pipe_barrier(PIPE_V);
140	        set_vector_mask(0, validCols);
141	        vsel(dst_f, tmp_f, dst_f, 1, 1, 1, 1, 8, 8, 8, 2);
142	        pipe_barrier(PIPE_V);
143	
144	        vconv_f322s32z(dst, dst_f, 1, 1, 1, 8, 8);
145	        pipe_barrier(PIPE_V);
146	    }
147	
148	    PTO_INTERNAL static void RemInstr(
149	        __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, __ubuf__ T* tmp, unsigned repeatTimes, unsigned validCols)
150	    {
151	        if constexpr (std::is_same_v<T, float> || std::is_same_v<T, float32_t>) {
152	            RemF32Instr(dst, src0, src1, tmp, repeatTimes, validCols);
153	        } else if constexpr (std::is_same_v<T, int32_t>) {
154	            RemInt32Instr(dst, src0, src1, tmp, repeatTimes, validCols);
155	        }
156	    }
157	};
