159	template <
160	    typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, typename TileDataTmp,
161	    unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned dstRowStride, unsigned src0RowStride = dstRowStride,
162	    unsigned src1RowStride = dstRowStride>
163	__tf__ PTO_INTERNAL void TRem(
164	    typename TileDataDst::TileDType __out__ dst, typename TileDataSrc0::TileDType __in__ src0,
165	    typename TileDataSrc1::TileDType __in__ src1, typename TileDataTmp::TileDType __in__ tmp, unsigned validRows,
166	    unsigned validCols)
167	{
168	    using T = typename TileDataDst::DType;
169	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
170	    __ubuf__ T* src0Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src0);
171	    __ubuf__ T* src1Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src1);
172	    __ubuf__ T* tmpPtr = (__ubuf__ T*)__cce_get_tile_ptr(tmp);
173	
174	    constexpr unsigned tmpRowStride = TileDataTmp::RowStride;
175	    uint16_t repeatTimes = CeilDivision(validCols, elementsPerRepeat);
176	
177	    for (uint16_t i = 0; i < validRows; i++) {
178	        __ubuf__ T* dstNext = dstPtr + i * dstRowStride;
179	        __ubuf__ T* s0Next = src0Ptr + i * src0RowStride;
180	        __ubuf__ T* s1Next = src1Ptr + i * src1RowStride;
181	
182	        RemOp<T, dstRowStride>::RemInstr(dstNext, s0Next, s1Next, tmpPtr, repeatTimes, validCols);
183	        set_mask_norm();
184	        set_vector_mask(-1, -1);
185	    }
186	}
